import 'models.dart';

class _GrammarSpec {
  const _GrammarSpec(
    this.id,
    this.level,
    this.title,
    this.rule,
    this.correct,
    this.wrong, {
    this.moreExamples = const <String>[],
    this.drills = const <_GrammarDrill>[],
  });
  final String id;
  final CefrLevel level;
  final String title;
  final String rule;
  final String correct;
  final String wrong;
  final List<String> moreExamples;
  final List<_GrammarDrill> drills;
}

class _GrammarDrill {
  const _GrammarDrill(
    this.prompt,
    this.first,
    this.second,
    this.third,
    this.correctIndex,
    this.explanation,
  );

  final String prompt;
  final String first;
  final String second;
  final String third;
  final int correctIndex;
  final String explanation;

  ChoiceQuestion build() => ChoiceQuestion(
        prompt: prompt,
        options: <String>[first, second, third],
        correctIndex: correctIndex,
        explanation: explanation,
      );
}

GrammarLesson _build(_GrammarSpec s) => GrammarLesson(
      id: s.id,
      level: s.level,
      title: s.title,
      explanation: s.rule,
      examples: <String>[s.correct, ...s.moreExamples],
      questions: s.drills.isNotEmpty
          ? s.drills.map((drill) => drill.build()).toList(growable: false)
          : <ChoiceQuestion>[
              ChoiceQuestion(
                prompt: 'Which sentence is the better example of this rule?',
                options: <String>[s.correct, s.wrong],
                correctIndex: 0,
                explanation: s.rule,
              ),
              ChoiceQuestion(
                prompt: 'Which statement is correct?',
                options: <String>[s.rule, 'The opposite rule applies in standard German.'],
                correctIndex: 0,
                explanation: s.rule,
              ),
            ],
    );

final List<GrammarLesson> supplementalGrammarLessons =
    _specs.map(_build).toList(growable: false);

